"""Migrated Meridian CRM 4.2 order_fulfilment workflow."""

from decimal import Decimal


def _positive_total(record: dict, tables: dict) -> bool:
    """Implement the VRL guard NVL(TOT_AMT, 0) > 0."""
    value = record.get("TOT_AMT", "")
    if value is None or value == "":
        value = 0
    return Decimal(str(value)) > Decimal("0")


def _account_not_on_credit_hold(record: dict, tables: dict) -> bool:
    """Implement LOOKUP(ACCT_MASTER, ACCT_ID, ACCT_ID, CRED_HOLD) <> 'Y'."""
    account_id = record.get("ACCT_ID", "")

    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG") != "Y" and row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "") != "Y"

    return True


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching transition in legacy document order."""
    output_record = dict(record)

    transitions = (
        ("E", "approve", "A", _positive_total, ("ORD_APPR",), ()),
        ("A", "ship", "S", None, ("ORD_SHIP",), ("shipped",)),
        ("S", "invoice", "I", None, ("ORD_INV",), ()),
        ("E", "cancel", "X", None, ("ORD_CANC",), ()),
        ("A", "cancel", "X", _account_not_on_credit_hold, ("ORD_CANC",), ()),
        ("I", "cancel", "X", None, ("ORD_CANC_INV",), ("credit_note",)),
    )

    for from_state, transition_event, to_state, guard, audits, notifies in transitions:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(output_record, tables):
            continue
        return {
            "state": to_state,
            "record": output_record,
            "audits": list(audits),
            "notifies": list(notifies),
            "matched": True,
        }

    return {
        "state": state,
        "record": output_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
